float smin(float a, float b, float k){
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}
float mapScene(vec3 p, float t, float pulse){
    float d = length(p) - (0.34 + pulse * 0.08);
    d = smin(d, length(p - vec3( 1.05 * sin(t * 0.90),  0.55 * cos(t * 0.70),
                                 0.25 * sin(t * 0.50))) - 0.30, 0.26);
    d = smin(d, length(p - vec3(-0.98 * cos(t * 0.62 + 1.7),
                                -0.62 * sin(t * 0.81 + 0.5),
                                 0.48 * cos(t * 0.44))) - 0.26, 0.22);
    d = smin(d, length(p - vec3( 0.40 * sin(t * 1.30 + 2.4),
                                 0.86 * cos(t * 0.55 + 1.1),
                                -0.55 * sin(t * 0.70))) - 0.21, 0.19);
    return d;
}
vec3 envColor(vec3 d, float t){
    float y = d.y * 0.5 + 0.5;
    vec3 sky    = mix(vec3(0.020, 0.040, 0.100), vec3(0.100, 0.300, 0.620),
                      smoothstep(0.45, 1.0, y));
    vec3 ground = mix(vec3(0.140, 0.030, 0.100), vec3(0.010, 0.010, 0.030),
                      smoothstep(0.0, 0.45, y));
    vec3 c = mix(ground, sky, smoothstep(0.42, 0.58, y));
    float k = max(0.0, dot(d, normalize(vec3(0.40, 0.80, -0.50))));
    k = k*k; k = k*k; k = k*k; k = k*k; k = k*k;          // pow(x,32)
    c += vec3(1.00, 0.95, 0.85) * k * 2.4;
    float bar = 1.0 - abs(d.y * 3.2); bar = max(bar, 0.0); bar = bar*bar*bar;
    c += u_color2 * bar * 0.35;
    float strip = 1.0 - abs(y - 0.72) * 9.0;
    strip = max(strip, 0.0); strip *= strip * strip;
    c += u_accent * strip * 0.50;
    return c;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2  res = u_resolution;
    vec2  uv  = (fragCoord * 2.0 - res) / min(res.x, res.y);
    float t   = u_time * u_speed;
    float pulse = u_audio_bass;

    vec3 ro = vec3(0.0, 0.0, -2.55);
    vec3 rd = normalize(vec3(uv, 1.75));
    ro.xy += (u_mouse - 0.5) * 0.20 + 0.07 * vec2(sin(t * 0.21), cos(t * 0.17));

    float s = 0.0, hit = 0.0;
    for (int i = 0; i < 48; i++){
        float d = mapScene(ro + rd * s, t, pulse);
        if (d < 0.0015){ hit = 1.0; break; }
        s += d * 0.78;
        if (s > 9.0) break;
    }
    vec3 col;
    if (hit > 0.5){
        vec3  p = ro + rd * s;
        float e = 0.0016;
        vec2  k = vec2(1.0, -1.0);
        vec3  n = normalize(k.xyy * mapScene(p + k.xyy * e, t, pulse) +
                            k.yyx * mapScene(p + k.yyx * e, t, pulse) +
                            k.yxy * mapScene(p + k.yxy * e, t, pulse) +
                            k.xxx * mapScene(p + k.xxx * e, t, pulse));
        col = envColor(reflect(rd, n), t);
        float f = 1.0 - clamp(dot(n, -rd), 0.0, 1.0); f = f*f*f;
        col += u_color1 * f * 0.90;
        float sp = max(0.0, dot(n, normalize(vec3(0.40, 0.85, -0.45))));
        sp = sp*sp*sp;
        col += vec3(1.0) * sp * 1.60;
        col *= 0.55 + 0.45 * (0.5 + 0.5 * n.y);
    } else {
        col = mix(vec3(0.115, 0.125, 0.215), vec3(0.020, 0.022, 0.052),
                  smoothstep(-0.35, 0.95, uv.y));
        col += u_color1 * 0.16 * exp(-abs(uv.y + 0.12) * 1.9)
             * (1.0 - smoothstep(-0.55, 0.70, uv.y));
        col += u_color2 * 0.055 * exp(-length(vec2(uv.x, uv.y + 0.42)) * 1.7);
        col *= 1.0 - 0.55 * exp(-length(vec2(uv.x * 1.1, (uv.y + 0.50) * 2.0)) * 2.4);
    }
    col += u_color1 * 0.085 * exp(-length(uv) * 2.0) * (0.6 + pulse);
    col *= 1.0 - 0.16 * dot(uv * 0.55, uv * 0.55);
    col  = pow(max(col, 0.0), vec3(0.95));
    fragColor = vec4(col, 1.0);
}

